mapper.select:
select
IFNULL（SUM(base.amount),0)amount
from (select
sum(PTRFLOW.AMOUNT)amount
from PTL_RECE_POSITION_FLOW PTRFLOW
where PTRFLOW.FINPROD_ID=#{finprodId,jdbcType=VARCHAR}

    and PTRFLOW.BRANCH>#{vDate}


    and PTRFLOW.BRANCH<#{mDate}


    and PTRFLOW.REC_TYPE=#{recType}

and PTRFLOW.HODING_TYPE=#{POSITION_TYPE_01}

    and PTRFLOW.CDATE=str_to_date(#{cDate},'%Y-%m-%d')


    and PTRFLOW.SEC_ACCT_ID=#{secAcctId,jdbcType=VARCHAR}


    and PTRFLOW.PORTFOLIO_ID=#{portfolioId,jdbcType=VARCHAR}


    and PTRFLOW.INV_AIM=#{invAim,jdbcType=VARCHAR}


union  all
select
sum(PTRFLOW.AMOUNT)amount
from PTL_RECE_POSITION PTRFLOW
where PTRFLOW.FINPROD_ID=#{finprodId,jdbcType=VARCHAR}

    and PTRFLOW.BRANCH>#{vDate}


    and PTRFLOW.BRANCH<#{mDate}


    and PTRFLOW.REC_TYPE=#{recType}

and PTRFLOW.HODING_TYPE=#{POSITION_TYPE_03}

    and PTRFLOW.CDATE=str_to_date(#{cDate},'%Y-%m-%d')


    and PTRFLOW.SEC_ACCT_ID=#{secAcctId,jdbcType=VARCHAR}


    and PTRFLOW.PORTFOLIO_ID=#{portfolioId,jdbcType=VARCHAR}


    and PTRFLOW.INV_AIM=#{invAim,jdbcType=VARCHAR}

)base

select base.PAY_DATE from
(
select
PAY_DATE
from PTL_RECE_POSITION_FLOW PTRFLOW
where PTRFLOW.FINPROD_ID=#{finprodId,jdbcType=VARCHAR}
and PTRFLOW.BRANCH=#{branch}
and PTRFLOW.REC_TYPE='03'
and PTRFLOW.HODING_TYPE ='03'
and PTRFLOW.INPUT_TYPE='04'
UNION ALL
SELECT PAY_DATE
FROM PTL_RECE_POSITION PTRFLOW
WHERE PTRFLOW.FINPROD_ID=#{finprodId,jdbcType=VARCHAR}
AND PTRFLOW.BRANCH      =#{branch}
AND PTRFLOW.REC_TYPE    ='03'
AND PTRFLOW.HODING_TYPE ='03'

    AND PTRFLOW.CDATE = #{cdate, jdbcType=DATE}


    AND PTRFLOW.PORTFOLIO_ID=#{portfolioId,jdbcType=VARCHAR}

)base
limit 1

select IFNULL(amount,0) from PTL_RECE_POSITION_FLOW
where  BRANCH=#{branch}
and FINPROD_ID = #{finprodId}
and PORTFOLIO_ID=#{portfolioId}
and rec_type=#{REC_TYPE_03}
and input_type=#{input_type}
